"""Symbolic type/aggregate visitors and the strict inverse reader.

``MainBuilder`` implements the toolkit harness-numbering contract: it walks an
entry's own parameters (in order) and its non-void result, reserving one
increasing ``xN`` identity for every visited bool, char, int, enum, string
buffer, array, or struct.  Scalars own one object; composites reserve an
identity but hold no object and then number their children recursively.  A
``String(N)`` reserves its buffer identity and then ``N`` character objects.
Aliases are transparent: they reserve nothing and add no path component.
Zero-length composites still reserve their own identity, void reserves none,
and an optional final Boolean object carries the pipe-acceptance flag.

The walk compiles into a flat pre-order program: the subtree of an identity is
contiguous, so :class:`ResultReader` recovers values (and canonical corpus
identity keys) in one descending pass with no recursion and no re-walking.
"""

from ast import NodeVisitor
from typing import Any, Dict, List, Optional, Tuple

from eywa.ast import Array, Bool, Char, Enum, Int, String, Struct, Type, Void

# Compiled layout node kinds.
K_BOOL = 0
K_CHAR = 1
K_INT = 2
K_ENUM = 3
K_STRING = 4
K_ARRAY = 5
K_STRUCT = 6
K_FLAG = 7

# Byte widths, per the published contract.
WIDTH_BOOL = 1
WIDTH_CHAR = 1
WIDTH_ENUM = 4


class TestError(Exception):
    """A recorded symbolic object cannot be recovered as documented."""


class TypeBuilder(NodeVisitor):
    """A class that maps an Eywa type to a C type and harness byte width."""

    @staticmethod
    def build(type: Type) -> Tuple[str, int]:
        """Convert an Eywa type to its C spelling and symbolic byte width."""
        return TypeBuilder().visit(type)

    def visit_Void(self, node):
        return "void", 0

    def visit_Bool(self, node):
        return "bool", WIDTH_BOOL

    def visit_Char(self, node):
        return "char", WIDTH_CHAR

    def visit_Int(self, node):
        return {1: "uint8_t", 2: "uint16_t", 4: "uint32_t",
                8: "uint64_t"}[node.bytes], node.bytes

    def visit_String(self, node):
        # The buffer identity owns no object: its characters do.
        return "char", -node.maxsize - 1

    def visit_Enum(self, node):
        return node.name, WIDTH_ENUM

    def visit_Array(self, node):
        return "aggregate", 0

    def visit_Struct(self, node):
        return node.name, 0

    def visit_Alias(self, node):
        return self.visit(node.type)


class TypeCollector(NodeVisitor):
    """Collect C declaration names in dependency-before-user postorder."""

    def __init__(self, results: List[str], done: set):
        self.result = results
        self.done = done

    @staticmethod
    def collect(type: Type, results: List[str], done=None):
        """Append the declaration names reachable from ``type``, once each."""
        TypeCollector(results, done if done is not None else set()).visit(type)

    def _seen(self, node) -> bool:
        marker = id(node)
        if marker in self.done:
            return True
        self.done.add(marker)
        return False

    def visit_Void(self, node):
        return None

    def visit_Bool(self, node):
        return None

    def visit_Char(self, node):
        return None

    def visit_Int(self, node):
        return None

    def visit_String(self, node):
        self._seen(node)
        return None

    def visit_Enum(self, node):
        if not self._seen(node):
            self.result.append(node.name)

    def visit_Array(self, node):
        if self._seen(node):
            return None
        self.visit(node.element_type)
        return None

    def visit_Struct(self, node):
        if self._seen(node):
            return None
        for field in node.fields.values():
            self.visit(field)
        self.result.append(node.name)
        return None

    def visit_Alias(self, node):
        if self._seen(node):
            return None
        self.visit(node.type)
        self.result.append(node.name)
        return None


class Layout(object):
    """The compiled symbolic harness of one entry."""

    __slots__ = ("nodes", "widths", "slots", "variables", "param_names",
                 "param_roots", "result_root", "flag_root", "key_limit")

    def __init__(self, nodes, widths, slots, param_names, param_roots,
                 result_root, flag_root, key_limit):
        self.nodes = nodes
        self.widths = widths
        self.slots = slots
        self.variables = len(nodes)
        self.param_names = param_names
        self.param_roots = param_roots
        self.result_root = result_root
        self.flag_root = flag_root
        # Identities below key_limit belong to entry parameters, which alone
        # carry corpus identity keys; result and flag objects do not.
        self.key_limit = key_limit


class MainBuilder(NodeVisitor):
    """Assign harness identities and compile one entry layout program."""

    def __init__(self):
        self.kinds: List[int] = []
        self.widths: List[int] = []
        self.data: List[Any] = []
        self.parents: List[int] = []
        self.comps: List[Any] = []
        self.objects: List[int] = []
        self.param_names: List[str] = []
        self.param_roots: List[int] = []
        self.result_root: Optional[int] = None
        self.flag_root: Optional[int] = None
        self.key_limit = 0
        self._parent = -1
        self._comp = None

    # -- identity reservation ------------------------------------------------
    def _reserve(self, kind, width, data):
        index = len(self.kinds)
        self.kinds.append(kind)
        self.widths.append(width)
        self.data.append(data)
        self.parents.append(self._parent)
        self.comps.append(self._comp)
        if width > 0:
            self.objects.append(index)
        return index

    def _children(self, owner: int, pairs):
        parent, comp = self._parent, self._comp
        self._parent = owner
        for component, child_type in pairs:
            self._comp = component
            self.visit(child_type)
        self._parent, self._comp = parent, comp

    # -- entry points --------------------------------------------------------
    def add_parameter(self, parameter):
        self._parent = -1
        self._comp = parameter.name
        root = self.visit(parameter.type)
        self.key_limit = len(self.kinds)
        self.param_names.append(parameter.name)
        self.param_roots.append(root)
        return root

    def add_result(self, parameter):
        if isinstance(Type.inner(parameter.type), Void):
            self.result_root = None
            return None
        self._parent = -1
        self._comp = parameter.name
        self.result_root = self.visit(parameter.type)
        return self.result_root

    def add_flag(self):
        parent, comp = self._parent, self._comp
        self._parent = -1
        self._comp = "bad_input"
        self.flag_root = self._reserve(K_FLAG, WIDTH_BOOL, None)
        self._parent, self._comp = parent, comp
        return self.flag_root

    # -- type visitors -------------------------------------------------------
    def visit_Void(self, node):
        raise TestError("void has no symbolic value")

    def visit_Bool(self, node):
        return self._reserve(K_BOOL, WIDTH_BOOL, None)

    def visit_Char(self, node):
        return self._reserve(K_CHAR, WIDTH_CHAR, None)

    def visit_Int(self, node):
        return self._reserve(K_INT, node.bytes, node.limit)

    def visit_Enum(self, node):
        return self._reserve(K_ENUM, WIDTH_ENUM, node.values)

    def visit_String(self, node):
        index = self._reserve(K_STRING, -1, None)
        self._children(index, [(i, node.char_type) for i in range(node.maxsize)])
        return index

    def visit_Array(self, node):
        index = self._reserve(K_ARRAY, -1, None)
        self._children(index, [(i, node.element_type) for i in range(node.maxsize)])
        return index

    def visit_Struct(self, node):
        index = self._reserve(K_STRUCT, -1, node.names)
        self._children(index, list(node.fields.items()))
        return index

    def visit_Alias(self, node):
        # Transparent: no identity reserved and no path component added.
        return self.visit(node.type)

    # -- finish --------------------------------------------------------------
    def _path(self, index) -> Tuple:
        parts = []
        while index >= 0:
            parts.append(self.comps[index])
            index = self.parents[index]
        parts.reverse()
        return tuple(parts)

    def finish(self) -> Layout:
        count = len(self.kinds)
        sizes = [1] * count
        for index in range(count - 1, 0, -1):
            parent = self.parents[index]
            if parent >= 0:
                sizes[parent] += sizes[index]
        nodes = tuple((self.kinds[i], self.widths[i], sizes[i], self.data[i])
                      for i in range(count))
        widths = tuple(self.widths)
        slots = tuple(("x%d" % i, self._path(i), widths[i]) for i in self.objects)
        return Layout(nodes, widths, slots, tuple(self.param_names),
                      tuple(self.param_roots), self.result_root,
                      self.flag_root, self.key_limit)


def build_layout(module, has_pipes: bool) -> Layout:
    """Compile the entry harness for one module signature."""
    builder = MainBuilder()
    for parameter in module.inputs:
        builder.add_parameter(parameter)
    builder.add_result(module.result)
    if has_pipes:
        builder.add_flag()
    return builder.finish()


class ResultReader(NodeVisitor):
    """Recover typed symbolic values from a strict KTEST object inventory."""

    __slots__ = ("layout", "nodes", "key_limit")

    def __init__(self, layout: Layout):
        self.layout = layout
        self.nodes = layout.nodes
        self.key_limit = layout.key_limit

    def read(self, objs):
        """Return (parameter values, identity key, result value, flag value).

        ``objs`` is indexed by reserved identity and already width-validated;
        non-object identities (composites and string buffers) hold ``None``.
        """
        nodes = self.nodes
        count = len(nodes)
        key_limit = self.key_limit
        vals: List[Any] = [None] * count
        keys: List[Any] = [None] * key_limit
        for index in range(count - 1, -1, -1):
            kind, width, size, data = nodes[index]
            if kind < K_STRING:
                raw = objs[index]
                if raw is None:
                    raise TestError("missing object x%d" % index)
                if kind == K_BOOL:
                    if len(raw) != 1 or raw[0] > 1:
                        raise TestError("bad bool x%d" % index)
                    value = raw[0] == 1
                elif kind == K_CHAR:
                    value = chr(raw[0])
                elif kind == K_INT:
                    value = int.from_bytes(raw, "little")
                    if value >= data:
                        raise TestError("padded int x%d" % index)
                else:
                    slot = int.from_bytes(raw, "little")
                    if slot >= len(data):
                        raise TestError("enum index x%d" % index)
                    value = data[slot]
                vals[index] = value
                if index < key_limit:
                    keys[index] = value
            elif kind == K_FLAG:
                raw = objs[index]
                if raw is None or raw[0] > 1:
                    raise TestError("bad flag x%d" % index)
                vals[index] = raw[0] == 1
            elif kind == K_STRING:
                parts = []
                for child in range(index + 1, index + size):
                    ch = vals[child]
                    if ch == "\x00":
                        break
                    parts.append(ch)
                value = "".join(parts)
                vals[index] = value
                if index < key_limit:
                    keys[index] = value
            elif kind == K_ARRAY:
                items = []
                identities = []
                want_keys = index < key_limit
                child = index + 1
                end = index + size
                while child < end:
                    items.append(vals[child])
                    if want_keys:
                        identities.append(keys[child])
                    child += nodes[child][2]
                vals[index] = items
                if want_keys:
                    keys[index] = ("a", tuple(identities))
            else:
                child = index + 1
                end = index + size
                if index < key_limit:
                    record = {}
                    paired = []
                    for name in data:
                        record[name] = vals[child]
                        paired.append((name, keys[child]))
                        child += nodes[child][2]
                    vals[index] = record
                    keys[index] = ("s", tuple(paired))
                else:
                    record = {}
                    for name in data:
                        record[name] = vals[child]
                        child += nodes[child][2]
                    vals[index] = record
        layout = self.layout
        values = [vals[root] for root in layout.param_roots]
        identities = tuple((name, keys[root])
                           for name, root in zip(layout.param_names, layout.param_roots))
        result = None if layout.result_root is None else vals[layout.result_root]
        flag = None if layout.flag_root is None else vals[layout.flag_root]
        return values, identities, result, flag
